import {realMentor,realTasks} from './server-ui.js';
import {esc,icon,panelHeader,sourceButton} from './ui.js';
import {LEVELS,STAGES,ancestors,recommendedRoute,taskKey} from './domain.js';
import {BATCHES} from './seed.js';
export {taskKey};
function sourceList(n,s){return n.refs.map(id=>{const src=s.sources.find(v=>v.id===id);return`<article class="source-card"><span class="tag">${esc(src.type)}</span><h4>${esc(src.title)}</h4><p>${esc(src.date)} · ${esc(src.locator)}</p>${sourceButton(id)}</article>`}).join('')}
const tabLabels={book:'动态教材',profile:'学习档案',practice:'项目实践',mentor:'AI 导师',exercise:'练习验证'};
export function renderNode(n,s,ui,store){
 const historical=ui.version!==null,tabs=Object.entries(tabLabels);let body='';
 if(ui.tab==='book')body=`<p class="node-summary">${esc(n.summary)}</p><div class="section-heading"><span>核心概念</span><small>${store.mode==='server'?'资料整理稿':'示例教材'} · v${s.version}</small></div>${n.concepts.map(([title,text],i)=>`<article class="concept"><span class="concept-index">0${i+1}</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></article>`).join('')}${n.notes.length?`<div class="update-note"><span class="overline">INCREMENTAL NOTES</span><h3>后来补充的理解</h3>${n.notes.map(note=>`<p>${esc(note.text)}</p>${sourceButton(note.source,'追溯本次补充')}`).join('')}</div>`:''}<div class="section-heading"><span>前置能力</span></div><div class="chips">${n.prereqs.map(id=>`<button data-node="${id}">${esc(s.nodes.find(v=>v.id===id).title)} ↗</button>`).join('')||'<span class="muted">这是一个基础起点。</span>'}</div><div class="why-learn"><strong>为什么学它？</strong><p>${n.kind==='project'?'项目把分散能力连接成完整交付，只有可核对证据才能支持阶段判断。':`它支持${s.nodes.filter(v=>v.prereqs.includes(n.id)).map(v=>v.title).join('、')||'后续项目实践'}。先补齐前置知识，再完成一次可验证的练习。`}</p></div>`;
 if(ui.tab==='profile')body=`<div class="notice">${icon('source')}原始来源与 AI 补充独立保留，可逐条追溯。</div><div class="section-heading"><span>我的学习轨迹</span><small>${n.refs.length} 条来源</small></div>${n.refs.map((id,i)=>{const src=s.sources.find(v=>v.id===id);return`<article class="timeline-item"><span class="timeline-dot"></span><small>${esc(src.date)} / ${i?'新增关联':'首次记录'}</small><h3>${esc(src.title)}</h3><p>${i?'本次资料补充到原节点，旧内容继续保留。':'记录了当时的问题、解释与操作情况。原始资料包含完整示例片段。'}</p>${sourceButton(id,'查看当时的记录')}</article>`}).join('')}<div class="section-heading"><span>原始资料</span></div>${sourceList(n,s)}`;
 if(ui.tab==='practice'){
  const projects=n.kind==='project'?[n]:s.nodes.filter(p=>p.kind==='project'&&ancestors(s.nodes,p.id).has(n.id));
  body=`<p class="panel-intro">${n.kind==='project'?'阶段来自项目记录，讨论、实现、测试和上线分别保留。':'把能力放回业务场景。关联项目并不代表该能力已经通过验证。'}</p>${projects.map(p=>`<article class="project-evidence"><div class="card-title"><h3>${esc(p.title)}</h3><span class="stage-tag">${p.stage}</span></div><p>${esc(p.summary)}</p><div class="stage-steps">${STAGES.map(stage=>`<span class="${p.stage===stage?'current':''}">${stage}</span>`).join('')}</div>${p.evidence.map(e=>`<details><summary>${esc(e[0])}</summary><p>${esc(e[2])}</p></details>`).join('')}${sourceButton(p.refs.at(-1),'查看项目原始记录')}${p.id!==n.id?`<button class="text-button" data-node="${p.id}" data-node-tab="practice">进入项目节点 ↗</button>`:''}</article>`).join('')||'<div class="empty-card">目前没有关联项目。先完成一次练习，再留下实践记录。</div>'}<div class="section-heading"><span>节点实践记录</span></div>${n.evidence.map(e=>`<article class="evidence-record"><h3>${esc(e[0])}</h3><code>${esc(e[1])}</code><p>${esc(e[2])}</p></article>`).join('')}<div class="notice warning">${store.mode==='server'?'来源中的陈述尚需独立验证。':'所有项目与记录均为虚构示例。'}讨论方案不等于代码已改、测试通过或已上线。</div>`;
 }
 if(ui.tab==='mentor'&&store.mode==='server')body=realMentor(n,ui);
 if(ui.tab==='mentor'&&store.mode!=='server'){
  const response=ui.mentor[n.id];
  body=`<div class="notice">${icon('workflow')}导师交互演示 · 仅使用预置回答，未调用模型。</div><div class="context-box"><span class="overline">CONTEXT LOADED</span><p><strong>当前节点</strong>${esc(n.title)}</p><p><strong>学习目标</strong>${store.target==='ai'?'构建可靠的 AI 应用':'独立交付一个后端项目'}</p><p><strong>路线 / 来源</strong>v${s.version} · ${n.refs.length} 条可追溯记录</p></div><h3 class="small-heading">从一个具体问题开始</h3><div class="mentor-prompts">${[['project','用项目解释这个知识'],['prereq','我应该先学什么？'],['mistake','我最容易误解什么？']].map(([key,text])=>`<button data-mentor="${key}">${text}<span>↗</span></button>`).join('')}</div>${response?`<article class="mentor-answer"><span class="overline">示例导师 / ${esc(n.title)}</span><p>${esc(response==='project'?`在${s.nodes.find(p=>p.kind==='project'&&ancestors(s.nodes,p.id).has(n.id))?.title||'一个虚构应用'}中，${n.concepts[0][1]} 你可以先完成「${n.tasks[0]}」，再记录输入、结果和验证方法。`:response==='prereq'?n.prereqs.length?`先理解 ${n.prereqs.map(id=>s.nodes.find(v=>v.id===id).title).join('、')}，它们为当前节点提供基础。你目前的证据等级为「${LEVELS[n.level]}」，先做一次独立练习，而不是直接提升掌握状态。`:'这是一个基础节点。先用自己的话解释概念，再完成一个小练习并留下记录。':`${n.mistakes[0][0]}。${n.mistakes[0][1]} 因此需要把讨论、实际操作和验证证据分别记录。`)}</p>${sourceButton(n.refs[0],'本回答的示例依据')}</article>`:''}`;
 }
 if(ui.tab==='exercise'){
  const choice=store.answers[taskKey(s.version,n.id,'quiz')],rbac=['rbac','scope'].includes(n.id);
  const question=rbac?'哪种记录可以支持权限方案已经验证？':'哪种情况可以支持一项能力已经过实践验证？';
  const options=rbac?['前端已隐藏管理员按钮','后端实现规则，隔离用例验证角色与数据范围','AI 在总结中写“已上线”']:['曾经向 AI 问过这个知识','独立完成实践，并保留可核对的测试结果','已把所有练习勾选完成'];
  body=`<p class="panel-intro">练习用于发现知识缺口。一次选择题答对、任务勾选完成，都不会自动提升能力等级。</p><div class="section-heading"><span>理解检查</span><small>示例选择题</small></div><h3 class="quiz-question">${question}</h3><div class="quiz-options">${options.map((text,i)=>`<button data-answer="${i}" ${historical?'disabled':''} class="${choice===i?(i===1?'correct':'incorrect'):''}"><span>${['A','B','C'][i]}</span>${text}</button>`).join('')}</div>${Number.isInteger(choice)?`<div class="answer-feedback ${choice===1?'correct':'incorrect'}">${choice===1?'回答正确。证据需要包含实际行为和可核对结果；仍不能据此判定独立掌握。':'还需要实践与验证证据。正确答案是 B；问过、勾选或 AI 自述都不能替代验证。'}</div>`:''}<div class="section-heading"><span>下一次实践</span><small>仅记录练习进度</small></div>${n.tasks.map((text,i)=>`<label class="task-row"><input type="checkbox" data-task="${i}" ${store.tasks[taskKey(s.version,n.id,i)]?'checked':''} ${historical?'disabled':''}><span>${esc(text)}</span></label>`).join('')}<div class="section-heading"><span>常见错误</span></div>${n.mistakes.map(([title,text])=>`<article class="mistake"><h3>! ${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}`;
 }
 if(ui.tab==='exercise'&&store.mode==='server')body=realTasks(n,s,ui,store,taskKey);
 const levelBand=n.kind==='project'?`<span class="stage-tag">项目状态 · ${n.stage}</span><span class="meta-note">与能力掌握状态分开记录</span>`:`<span class="state-badge level-${n.level}">${LEVELS[n.level]}</span><span class="meta-note">${store.mode==='server'?'依据资料 · 尚需实践验证':'依据示例资料 · 非 AI 自动判定'}</span>`;
 return `${panelHeader(n.kind==='project'?'PROJECT SPACE':'KNOWLEDGE SPACE',n.title)}<div class="node-meta">${levelBand}</div><div class="node-tabs" role="tablist" aria-label="节点学习空间">${tabs.map(([id,title])=>`<button role="tab" id="tab-${id}" aria-selected="${ui.tab===id}" aria-controls="node-content" data-tab="${id}" class="${ui.tab===id?'active':''}">${title}</button>`).join('')}</div><div class="panel-content" id="node-content" role="tabpanel" aria-labelledby="tab-${ui.tab}">${body}</div><div class="panel-bottom"><button class="outline-button" data-action="highlight" aria-pressed="${ui.highlight}">${icon('route')}${ui.highlight?'退出路径高亮':'高亮前置路径'}</button><span>来源保留 · 历史可回看</span></div>`;
}
export function renderSync(s,ui){const b=BATCHES[ui.batch],applied=s.applied.includes(b.id);return`${panelHeader('IMPORT & INCREMENTAL SYNC','让新知识，接上旧经验。')}<div class="panel-content"><div class="notice">此处只载入内置虚构资料。知识提取与对齐结果为预置演示，不接收私人聊天，不调用模型。</div><div class="segmented"><button data-batch="history" class="${ui.batch==='history'?'active':''}">历史资料导入</button><button data-batch="sync" class="${ui.batch==='sync'?'active':''}">Skill 主动同步</button></div>${applied?`<div class="sync-complete">${icon('check')}<h3>这份资料已经同步。</h3><p>相同批次不会重复创建节点或版本。</p><button data-action="history" class="text-button">查看路线历史 ↗</button></div>`:ui.syncStep==='choose'?`<div class="import-art">${icon('import')}<span>${ui.batch==='history'?'01 / HISTORY IMPORT':'02 / SKILL SYNC'}</span></div><h3>${ui.batch==='history'?'体验一次历史盘点':'体验一次局部更新'}</h3><p class="panel-intro">${ui.batch==='history'?'示例学习资料涉及 FastAPI、事务与 Docker。系统将识别新节点，补充关系，并保留原始资料。':'一段权限讨论同时关联个人 RBAC 知识与客户协作后台，并包含一个必须处理的阶段推断冲突。'}</p>${b.sources.map(src=>`<article class="source-card"><span class="tag">${src.type}</span><h4>${src.title}</h4><p>仅演示本次选定片段，不读取其他资料。</p><button class="source-link" data-batch-source="${src.id}">${icon('source')}阅读示例原文 ↗</button></article>`).join('')}<button class="primary-button wide" data-action="preview-batch">载入示例并预览变更 ${icon('arrow')}</button>`:`<div class="section-heading"><span>待审阅的增量变更</span><small>保留当前 v${s.version}</small></div><p class="panel-intro">${b.summary}。确认后生成新版本，原始节点与历史继续保留。</p>${b.addNodes.map(n=>`<article class="change-row"><span class="change-type">新增</span><div><h4>${n.title}</h4><p>${LEVELS[n.level]} · 前置关系已对齐，不重复创建已有知识。</p></div></article>`).join('')}${b.updates.map(u=>`<article class="change-row"><span class="change-type append">补充</span><div><h4>${s.nodes.find(n=>n.id===u.id).title}</h4><p>${u.notes?.[0]?.text||'增加前置关系与来源引用，原有内容不覆盖。'}</p></div></article>`).join('')}${b.conflict?`<article class="conflict-card"><span class="overline">! REVIEW REQUIRED</span><h3>${b.conflict.title}</h3><div class="conflict-values"><span>当前：${b.conflict.existing}</span><span class="wrong-claim">待审推断：${b.conflict.incoming}</span></div><p>${b.conflict.reason}</p><label class="conflict-ack"><input type="checkbox" id="conflict-ack" ${ui.ackConflict?'checked':''}>保留「计划」状态，将未经证实的「已上线」仅记录为冲突。</label></article>`:''}<div class="notice">能力等级不会因新讨论或任务勾选而自动升级。项目阶段也不会按 AI 摘要自动推进。</div><button class="primary-button wide" data-action="apply-batch" ${b.conflict&&!ui.ackConflict?'disabled':''}>确认更新，保留旧版本 ${icon('arrow')}</button><button class="text-button back-button" data-action="sync-back">返回资料选择</button>`}</div>`}
export function renderHistory(store,ui){return`${panelHeader('ROUTE HISTORY','每次生长，都有来路。')}<div class="panel-content"><p class="panel-intro">每次资料合并创建一个独立快照。历史视图只读，旧节点、关系与原始片段不会被新路线覆盖。</p>${[...store.snapshots].reverse().map(s=>`<article class="version-card ${ui.version===s.version?'selected':''}"><div class="card-title"><span class="version-number">v${s.version}</span><h3>${esc(s.title)}</h3>${s===store.snapshots.at(-1)?'<span class="tag">当前</span>':''}</div><small>${new Date(s.time).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</small><p>${esc(s.summary)}</p><div class="version-stats"><span>${s.nodes.length} 个节点</span><span>${s.sources.length} 条原始资料</span></div><button class="outline-button" data-version="${s.version}">${s===store.snapshots.at(-1)?'查看当前路线':'查看历史快照'} ↗</button></article>`).join('')}${store.snapshots.at(-1).conflicts.length?`<div class="section-heading"><span>已处理的冲突</span></div>${store.snapshots.at(-1).conflicts.map(c=>`<article class="conflict-card"><h3>${esc(c.title)}</h3><p>${esc(c.resolution)}</p>${sourceButton(c.source,'核对冲突原文')}</article>`).join('')}`:''}</div>`}
export function renderGoal(s,store){const route=recommendedRoute(s,store.target);return`${panelHeader('GOAL & LEARNING PATH','我在哪，下一步去哪。')}<div class="panel-content"><label class="field-label" for="goal-select">当前目标</label><select id="goal-select" class="wide-select"><option value="backend" ${store.target==='backend'?'selected':''}>独立交付一个后端项目</option><option value="ai" ${store.target==='ai'?'selected':''}>构建可靠的 AI 应用</option></select><p class="panel-intro">以下路径按示例项目的前置关系计算。优先补齐基础和证据缺口，不因为讨论次数多就判断掌握。</p><div class="section-heading"><span>推荐下一步</span><small>${route.length} 项待补齐</small></div><ol class="route-list">${route.map(n=>`<li><button data-node="${n.id}"><span>${icon(n.icon)}</span><div><strong>${esc(n.title)}</strong><small>${LEVELS[n.level]} · ${n.prereqs.length?'先理解 '+n.prereqs.map(id=>s.nodes.find(v=>v.id===id).title).join('、'):'项目需要的基础起点'}</small></div><span>↗</span></button></li>`).join('')}</ol><div class="notice">这是一条基于依赖和当前证据等级的示例路径；完整产品将加入用户经历与目标的 AI 分析。</div></div>`}
